// One item per Gmail message, flattened into a stable shape. Relay created a separate run
// per email; an n8n poll can emit several at once, so every downstream node keys off
// message_id instead of assuming one email per execution.
const MAX_BODY = 2700;                       // Relay truncated the model input at 2700 chars.
const ALLOWED = ['.pdf', '.doc', '.docx'];   // Relay's loop filter dropped everything else.

function toText(value) {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'object') {
    if (typeof value.text === 'string') return value.text;
    if (Array.isArray(value.value)) {
      return value.value.map((v) => v.address || v.name || '').filter(Boolean).join(', ');
    }
  }
  return String(value);
}

function stripHtml(html) {
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// The .NET webhook compares received_at against UtcNow, so always hand it ISO-8601 UTC
// rather than Gmail's RFC 2822 date.
function toIsoUtc(value) {
  if (value === undefined || value === null || value === '') return null;
  const asNumber = Number(value);
  const looksEpoch = Number.isFinite(asNumber) && String(value).trim().length >= 10;
  const date = new Date(looksEpoch ? asNumber : String(value));
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

// Drive rejects path separators and control characters in folder names.
function safeName(value) {
  return String(value || '')
    .replace(/[\\/\r\n\t]+/g, ' ')
    .replace(/\s{2,}/g, ' ')
    .trim()
    .slice(0, 120);
}

const out = [];

for (const item of $input.all()) {
  const json = item.json || {};
  const headers = json.headers || {};
  const binary = item.binary || {};

  const from = toText(json.from) || toText(headers.from) || toText(headers.From);
  const fromEmail = from.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);

  const body =
    toText(json.text) ||
    toText(json.textPlain) ||
    stripHtml(json.html || json.textHtml) ||
    toText(json.snippet);

  // Only the extensions Relay's loop accepted count as attachments anywhere downstream,
  // so an email carrying nothing but images never creates an empty Drive folder.
  const attachmentKeys = [];
  const attachmentNames = [];
  for (const key of Object.keys(binary)) {
    if (!key.startsWith('attachment_')) continue;
    const fileName = String((binary[key] || {}).fileName || '');
    if (!ALLOWED.some((ext) => fileName.toLowerCase().endsWith(ext))) continue;
    attachmentKeys.push(key);
    attachmentNames.push(fileName);
  }

  const receivedAt =
    toIsoUtc(json.date) ||
    toIsoUtc(headers.date || headers.Date) ||
    toIsoUtc(json.internalDate) ||
    new Date().toISOString();

  const subject = toText(json.subject) || toText(headers.subject) || toText(headers.Subject);

  out.push({
    json: {
      message_id: String(json.id || json.messageId || ''),
      thread_id: String(json.threadId || ''),
      subject,
      from,
      from_email: fromEmail ? fromEmail[0].toLowerCase() : '',
      mail_content: body,
      truncated_body: body.length > MAX_BODY ? body.slice(0, MAX_BODY) + '... [truncated]' : body,
      received_at: receivedAt,
      folder_name: safeName('Support - ' + (subject || '(no subject)') + ' - ' + receivedAt),
      attachment_keys: attachmentKeys,
      attachment_names: attachmentNames,
      attachment_count: attachmentKeys.length
    }
  });
}

return out;

