// Turn the model response into the flat record the Risebird webhook expects. Index
// alignment with the filter output is safe: the AI node is strictly 1:1 with its input.
const INTENTS = [
  'New interview request',
  'New candidate submission',
  'Candidate status update',
  'Candidate reports',
  'Stop interviews',
  'Cold candidate',
  'Interviewer misalignment',
  'Interviewer replacement',
  'Interviewer false negative',
  'Interviewer false positive',
  'Score rubric concerns',
  'Candidate bad experience with Risebird',
  'Candidate bad experience with interviewer',
  'Delay in scheduling',
  'Delay in getting interviews started',
  'Delay in report sharing',
  'Good experience with Risebird',
  'Poor experience with Risebird support team',
  'Interviewer no-show',
  'Quality control issues'
];

// Covers both the simplified and the raw Responses-API shapes.
function responseText(raw) {
  if (!raw) return '';
  if (typeof raw === 'string') return raw;
  if (typeof raw.output_text === 'string' && raw.output_text.trim()) return raw.output_text;
  if (Array.isArray(raw.output)) {
    for (const entry of raw.output) {
      const parts = entry && Array.isArray(entry.content) ? entry.content : [];
      for (const part of parts) {
        if (part && typeof part.text === 'string' && part.text.trim()) return part.text;
      }
    }
  }
  if (raw.message && typeof raw.message.content === 'string') return raw.message.content;
  if (typeof raw.content === 'string') return raw.content;
  if (typeof raw.text === 'string') return raw.text;
  return '';
}

function toObject(raw) {
  const text = responseText(raw);
  if (!text) {
    return raw && typeof raw === 'object' && typeof raw.webhook_intent === 'string' ? raw : {};
  }
  const cleaned = String(text)
    .replace(/^\s*```(?:json)?/i, '')
    .replace(/```\s*$/, '')
    .trim();
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    const braced = cleaned.match(/\{[\s\S]*\}/);
    if (braced) {
      try {
        return JSON.parse(braced[0]);
      } catch (inner) {
        return {};
      }
    }
    return {};
  }
}

// The webhook treats "null" and "" the same, so collapse the model's placeholder strings.
function textOrNull(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  if (!text) return null;
  const lowered = text.toLowerCase();
  if (lowered === 'null' || lowered === 'n/a' || lowered === 'none' || lowered === 'undefined') return null;
  return text;
}

function toBool(value) {
  if (typeof value === 'boolean') return value;
  const text = String(value === undefined || value === null ? '' : value).trim().toLowerCase();
  return text === 'true' || text === 'yes' || text === '1';
}

// The server only accepts a skill channel id that is exactly 10 alphanumeric characters,
// so anything else is dropped here rather than sent and silently ignored.
function skillChannelId(value) {
  const text = textOrNull(value);
  return text && /^[A-Za-z0-9]{10}$/.test(text) ? text : null;
}

const contexts = $('Exclude internal/personal senders').all();
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const context = (contexts[i] && contexts[i].json) || {};
  const parsed = toObject((items[i] && items[i].json) || {});
  const parseFailed = Object.keys(parsed).length === 0;

  // An unusable model response must not invent an intent — Relay fell back to
  // "Cold candidate", which routes the ticket to manual review.
  let intent = textOrNull(parsed.webhook_intent) || '';
  if (!INTENTS.includes(intent)) {
    intent = INTENTS.find((v) => v.toLowerCase() === intent.toLowerCase()) || 'Cold candidate';
  }

  const names = Array.isArray(context.attachment_names) ? context.attachment_names : [];

  // resume_url / resume_drive_url stay null here: nothing has been uploaded yet. They are
  // filled in by "Collect uploads" once Drive has handed back real links.
  const associations = (Array.isArray(parsed.resume_associations) ? parsed.resume_associations : [])
    .filter((a) => a && typeof a === 'object')
    .map((a) => ({
      resume_url: null,
      resume_filename: textOrNull(a.resume_filename),
      skill_channel_id: skillChannelId(a.skill_channel_id),
      job_title: textOrNull(a.job_title),
      candidate_name: textOrNull(a.candidate_name)
    }));

  // Auto-scheduling needs every field, so a partial candidate is dropped rather than
  // half-scheduled.
  const schedule = (Array.isArray(parsed.candidate_schedule_data) ? parsed.candidate_schedule_data : [])
    .filter((c) => c && typeof c === 'object')
    .map((c) => ({
      candidate_name: textOrNull(c.candidate_name),
      candidate_email: textOrNull(c.candidate_email),
      interview_date: textOrNull(c.interview_date),
      interview_time: textOrNull(c.interview_time),
      timezone: textOrNull(c.timezone) || 'IST',
      skill_channel_id: skillChannelId(c.skill_channel_id),
      resume_drive_url: null,
      resume_filename: null
    }))
    .filter((c) => c.candidate_name && c.interview_date && c.interview_time && c.skill_channel_id);

  out.push({
    json: {
      message_id: context.message_id || '',
      sender_email: context.from_email || '',
      subject: context.subject || '',
      mail_content: context.mail_content || '',
      received_at: context.received_at || new Date().toISOString(),
      folder_name: context.folder_name || 'Support - (no subject)',
      attachment_count: Number(context.attachment_count || 0),
      attachment_names: names,
      webhook_intent: intent,
      job_title: textOrNull(parsed.job_title),
      skill_channel_id: skillChannelId(parsed.skill_channel_id),
      primary_specialization: textOrNull(parsed.primary_specialization),
      mail_body_intent: textOrNull(parsed.mail_body_intent),
      attachment_job_description: toBool(parsed.attachment_job_description),
      attachment_pdf: toBool(parsed.attachment_pdf) || names.some((n) => String(n).toLowerCase().endsWith('.pdf')),
      attachment_resumes: toBool(parsed.attachment_resumes),
      drive_folder_link: null,
      resume_drive_urls: [],
      resume_filenames: [],
      resume_associations: associations,
      candidate_schedule_data: schedule,
      summary_mail: textOrNull(parsed.summary_mail) || '',
      summary_candidates: textOrNull(parsed.summary_candidates),
      summary_interview_scores: textOrNull(parsed.summary_interview_scores),
      ai_parse_failed: parseFailed
    }
  });
}

return out;

// One item per qualifying attachment. Files are pulled back off the trigger by message id
// so that a poll carrying several emails never uploads one sender's resume into another
// sender's folder.
const ALLOWED = ['.pdf', '.doc', '.docx'];

const triggerByMessageId = new Map();
for (const item of $('Email received').all()) {
  const json = item.json || {};
  triggerByMessageId.set(String(json.id || json.messageId || ''), item);
}

// "Create folder" runs once per email that reached it and the IF node preserves order, so
// the folders line up index-wise with the attachment-bearing emails.
const emails = $('Parse classification')
  .all()
  .map((i) => i.json || {})
  .filter((e) => Number(e.attachment_count || 0) > 0);
const folders = $('Create folder').all().map((i) => i.json || {});

const out = [];

for (let i = 0; i < emails.length; i++) {
  const email = emails[i];
  const folder = folders[i] || {};
  const folderId = String(folder.id || '');
  const folderLink =
    folder.webViewLink || (folderId ? 'https://drive.google.com/drive/folders/' + folderId : '');

  const trigger = triggerByMessageId.get(String(email.message_id || ''));
  const binary = (trigger && trigger.binary) || {};

  for (const key of Object.keys(binary)) {
    if (!key.startsWith('attachment_')) continue;
    const file = binary[key] || {};
    const fileName = String(file.fileName || key);
    if (!ALLOWED.some((ext) => fileName.toLowerCase().endsWith(ext))) continue;

    out.push({
      json: {
        message_id: String(email.message_id || ''),
        fileName,
        folder_id: folderId,
        folder_link: folderLink
      },
      binary: { data: file }
    });
  }
}

return out;

// Fold the per-attachment uploads back into one item per email and tie each Drive link to
// the candidate it belongs to. Relay shipped bare URL and filename arrays and let the
// server pair them by position; doing the pairing here means a mis-ordered upload can no
// longer attach the wrong resume to a candidate.
const JD_PHRASES = ['job description', 'jobdescription', 'hiring brief', 'requirement'];

const uploads = $input.all();
const sources = $('Split attachments').all();

const byMessageId = new Map();

for (let i = 0; i < uploads.length; i++) {
  const source = ((sources[i] || {}).json) || {};
  const file = ((uploads[i] || {}).json) || {};
  const messageId = String(source.message_id || '');
  const url = file.webViewLink || (file.id ? 'https://drive.google.com/file/d/' + file.id + '/view' : '');
  if (!url) continue;

  if (!byMessageId.has(messageId)) {
    byMessageId.set(messageId, { folder_link: '', files: [] });
  }
  const bucket = byMessageId.get(messageId);
  if (!bucket.folder_link) bucket.folder_link = source.folder_link || '';
  bucket.files.push({ url, fileName: String(file.name || source.fileName || '') });
}

function normalize(value) {
  return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

// "jd" is matched as a whole word only — a substring test would flag Rajdeep_Sharma.pdf.
function looksLikeJobDescription(fileName) {
  const text = normalize(fileName);
  if (JD_PHRASES.some((phrase) => text.includes(normalize(phrase)))) return true;
  return text.split(' ').includes('jd');
}

// Loose name matching: a candidate is tied to a file only when their name tokens actually
// appear in the filename. Guessing here would hand HR the wrong person's resume.
function matchIndex(candidateName, files, used) {
  const tokens = normalize(candidateName).split(' ').filter((t) => t.length >= 3);
  if (!tokens.length) return -1;

  let best = -1;
  let bestScore = 0;
  for (let i = 0; i < files.length; i++) {
    if (used.has(i)) continue;
    const haystack = normalize(files[i].fileName);
    const score = tokens.filter((t) => haystack.includes(t)).length;
    if (score > bestScore) {
      bestScore = score;
      best = i;
    }
  }
  return bestScore > 0 ? best : -1;
}

const out = [];

for (const item of $('Parse classification').all()) {
  const record = { ...((item.json) || {}) };

  // Mirrors the IF condition, so an email never leaves this branch twice.
  if (Number(record.attachment_count || 0) === 0) continue;

  const bucket = byMessageId.get(String(record.message_id || '')) || { folder_link: '', files: [] };
  const files = bucket.files;

  // Everything is uploaded to the folder, but a JD is not a resume. Keeping it out of
  // resume_drive_urls is what lets the server recognise a JD-only "New interview request"
  // as a channel-creation request instead of queueing the JD for HR as a candidate.
  const resumeFiles = files.filter((f) => !looksLikeJobDescription(f.fileName));
  const candidateFiles = resumeFiles.length ? resumeFiles : files;

  record.drive_folder_link = bucket.folder_link || null;
  record.resume_drive_urls = candidateFiles.map((f) => f.url);
  record.resume_filenames = candidateFiles.map((f) => f.fileName);
  record.jd_drive_urls = files.filter((f) => looksLikeJobDescription(f.fileName)).map((f) => f.url);

  // resume_associations: real name match first, then fill the remainder in upload order —
  // the same positional pairing Relay relied on, but only for what is left over.
  const usedByAssociation = new Set();
  const associations = Array.isArray(record.resume_associations) ? record.resume_associations : [];
  const unmatchedAssociations = [];

  for (const association of associations) {
    const index = matchIndex(association.candidate_name, candidateFiles, usedByAssociation);
    if (index >= 0) {
      usedByAssociation.add(index);
      association.resume_url = candidateFiles[index].url;
      association.resume_filename = candidateFiles[index].fileName;
    } else {
      unmatchedAssociations.push(association);
    }
  }

  let cursor = 0;
  for (const association of unmatchedAssociations) {
    while (cursor < candidateFiles.length && usedByAssociation.has(cursor)) cursor++;
    if (cursor >= candidateFiles.length) break;
    usedByAssociation.add(cursor);
    association.resume_url = candidateFiles[cursor].url;
    association.resume_filename = candidateFiles[cursor].fileName;
  }
  record.resume_associations = associations;

  // candidate_schedule_data books real interviews, so only a genuine name match — or the
  // unambiguous single-candidate/single-file case — is allowed to set a resume URL. Anything
  // left null is still sent; the server falls back to the Drive folder for HR review.
  const usedBySchedule = new Set();
  const schedule = Array.isArray(record.candidate_schedule_data) ? record.candidate_schedule_data : [];
  const unmatchedSchedule = [];

  for (const candidate of schedule) {
    const index = matchIndex(candidate.candidate_name, candidateFiles, usedBySchedule);
    if (index >= 0) {
      usedBySchedule.add(index);
      candidate.resume_drive_url = candidateFiles[index].url;
      candidate.resume_filename = candidateFiles[index].fileName;
    } else {
      unmatchedSchedule.push(candidate);
    }
  }

  if (unmatchedSchedule.length === 1 && candidateFiles.length === 1 && usedBySchedule.size === 0) {
    unmatchedSchedule[0].resume_drive_url = candidateFiles[0].url;
    unmatchedSchedule[0].resume_filename = candidateFiles[0].fileName;
  }
  record.candidate_schedule_data = schedule;

  out.push({ json: record });
}

return out;

// Both branches converge here, so the payload is assembled identically whether or not the
// email carried attachments. Everything comes off the incoming item — no cross-node
// lookups — which is what keeps a multi-email poll from mixing two tickets together.
function nullIfBlank(value) {
  const text = value === undefined || value === null ? '' : String(value).trim();
  return text ? text : null;
}

const out = [];

for (const item of $input.all()) {
  const record = item.json || {};

  const associations = (Array.isArray(record.resume_associations) ? record.resume_associations : [])
    .filter((a) => a && a.resume_url);

  out.push({
    json: {
      sender_email: nullIfBlank(record.sender_email),
      subject: nullIfBlank(record.subject),
      mail_content: record.mail_content || '',
      received_at: record.received_at || new Date().toISOString(),
      webhook_intent: record.webhook_intent || 'Cold candidate',
      job_title: nullIfBlank(record.job_title),
      skill_channel_id: nullIfBlank(record.skill_channel_id),
      primary_specialization: nullIfBlank(record.primary_specialization),
      mail_body_intent: nullIfBlank(record.mail_body_intent),
      attachment_job_description: !!record.attachment_job_description,
      attachment_pdf: !!record.attachment_pdf,
      attachment_resumes: !!record.attachment_resumes,
      drive_folder_link: nullIfBlank(record.drive_folder_link),
      resume_drive_urls: Array.isArray(record.resume_drive_urls) ? record.resume_drive_urls : [],
      resume_filenames: Array.isArray(record.resume_filenames) ? record.resume_filenames : [],
      resume_associations: associations,
      candidate_schedule_data: Array.isArray(record.candidate_schedule_data) ? record.candidate_schedule_data : [],
      summary_mail: record.summary_mail || '',
      summary_candidates: nullIfBlank(record.summary_candidates),
      summary_interview_scores: nullIfBlank(record.summary_interview_scores),
      source: 'n8n'
    }
  });
}

return out;
